-- MARKER_E055_APPLY
CREATE TABLE IF NOT EXISTS `buddy_subarea` (
  `id` INT UNSIGNED NOT NULL, `map` SMALLINT UNSIGNED NOT NULL, `area` INT UNSIGNED NOT NULL,
  `squares` INT UNSIGNED NOT NULL, `centre_x` FLOAT NOT NULL, `centre_y` FLOAT NOT NULL,
  `min_level` TINYINT UNSIGNED NOT NULL, `max_level` TINYINT UNSIGNED NOT NULL,
  `area_name` VARCHAR(100) NOT NULL, `monsters` VARCHAR(255) NOT NULL, PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='617e12: parts of named areas, by monster kind and steep ground';
CREATE TABLE IF NOT EXISTS `buddy_subarea_square` (
  `subarea` INT UNSIGNED NOT NULL, `map` SMALLINT UNSIGNED NOT NULL, `sx` SMALLINT UNSIGNED NOT NULL, `sy` SMALLINT UNSIGNED NOT NULL,
  PRIMARY KEY (`map`, `sx`, `sy`), KEY (`subarea`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='617e12: which part each square of a split area belongs to (map squares, 1/16 grid)';
DELETE FROM `buddy_subarea`;
DELETE FROM `buddy_subarea_square`;
